// sql.js 已改为从国内 CDN 加载（不再内联 base64）。测试时从 CDN 下载引擎与 wasm 并注入沙箱。
const SQLJS_BASES = [
  'https://cdn.staticfile.org/sql.js/1.13.0/',
  'https://cdn.bootcdn.net/ajax/libs/sql.js/1.13.0/',
  'https://cdn.jsdelivr.net/npm/sql.js@1.13.0/dist/'
];
const _httpGet = url => new Promise((resolve, reject) => {
  const https = require('https');
  const req = https.get(url, res => {
    if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
      res.resume(); return _httpGet(res.headers.location).then(resolve, reject);
    }
    if (res.statusCode !== 200) { res.resume(); return reject(new Error('HTTP ' + res.statusCode + ' ' + url)); }
    const chunks = [];
    res.on('data', d => chunks.push(d));
    res.on('end', () => resolve(Buffer.concat(chunks)));
  });
  req.on('error', reject);
  req.setTimeout(20000, () => { req.destroy(new Error('timeout ' + url)); });
});

