const fs = require('fs');
const p = '分析产出/持仓面板/_selftest.js';
let src = fs.readFileSync(p, 'utf8');
const lines = src.split(/\r?\n/);

const pIdx = lines.findIndex(l => l.includes('const P = sandbox.__PANEL__;'));
if (pIdx < 0) throw new Error('P not found');

// 105..end → 包进 runTests()
const head = lines.slice(0, pIdx);
const tail = lines.slice(pIdx);

// tail 最后一行是 IIFE 收尾 '})().catch(...)'；把 '(async () => {' 改成 'async function runTests() {'，去掉尾部 '})().catch'
let t = tail.join('\n');
t = t.replace('(async () => {', 'async function runTests() {');
t = t.replace(/\}\)\(\)\.catch\(e => \{ console\.error\(e\); process\.exit\(1\); \}\);\s*$/, '}\n');

// 在 head 的 boot 成功分支里调用 runTests()
let h = head.join('\n');
h = h.replace(
  'vm.runInContext(main, sandbox);\n    mainStarted = true;',
  'vm.runInContext(main, sandbox);\n    mainStarted = true;\n    runTests().catch(e => { console.error(e && e.stack || e); process.exit(1); });'
);

const out = h + '\n' + t;
fs.writeFileSync(p, out, 'utf8');
console.log('rewritten. P index', pIdx + 1, 'new lines', out.split(/\r?\n/).length);

